  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    node_by_id = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_by_id[nid] = n
        children[nid] = []
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children[p].append(n['id'])

    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break

    retained = set(node_by_id.keys())
    symbol_counts = {}
    for n in nodes:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1

    # sort nodes by depth descending, then by id
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_order = []

    def get_retained_subtree(node_id):
        # return set of node ids in the retained subtree (including node_id)
        subtree = set()
        stack = [node_id]
        while stack:
            curr = stack.pop()
            if curr in retained:
                subtree.add(curr)
                for child in children[curr]:
                    if child in retained:
                        stack.append(child)
        return subtree

    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if nid == root_id:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        # check if any retained children
        has_retained_child = any(c in retained for c in children[nid])
        if has_retained_child:
            continue
        # Try removal
        subtree = get_retained_subtree(nid)
        # pre-check required symbols
        safe = True
        for sym in required_symbols:
            count_in_subtree = sum(1 for sid in subtree if node_by_id[sid]['symbol'] == sym)
            if symbol_counts[sym] - count_in_subtree <= 0:
                safe = False
                break
        if not safe:
            continue
        # Perform removal
        removed_order.append(nid)
        for sid in subtree:
            sym = node_by_id[sid]['symbol']
            symbol_counts[sym] -= 1
            retained.discard(sid)

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }
